import onnx
from onnx import TensorProto

m = onnx.load("onnx/model_fp16_trt.onnx", load_external_data=True)
g = m.graph

# 每个张量的消费者op集合
consumers = {}
for n in g.node:
    for x in n.input:
        consumers.setdefault(x, set()).add(n.op_type)

n_flip = 0
for n in g.node:
    if n.op_type != "Cast":
        continue
    for a in n.attribute:
        if a.name == "to" and a.i == TensorProto.FLOAT:
            outs = set()
            for o in n.output:
                outs |= consumers.get(o, set())
            # 喂给 Resize(尺度/数据须fp32) 或图输出的保持fp32
            if "Resize" in outs:
                continue
            a.i = TensorProto.FLOAT16
            n_flip += 1

onnx.save(m, "onnx/model_fp16_trt.onnx")
print(f"已把 {n_flip} 个 Cast(to=fp32) 改为 fp16 (不含喂给Resize的)")
